-- Migration: NFDI-001C Canonical Food Seasonality & Climate Intelligence
-- Normalized additive table with RLS and ICMR-NIN verified seasonal food knowledge.

create table if not exists public.ingredient_seasonality (
  id uuid primary key default gen_random_uuid(),
  ingredient_key text not null,
  season text not null check (season in ('summer', 'monsoon', 'winter', 'all_season')),
  region text not null default 'maharashtra_western_india',
  availability_status text not null check (availability_status in ('peak', 'available', 'scarce', 'unknown')),
  culinary_suitability text check (culinary_suitability in ('cooling', 'warming', 'digestive', 'neutral', 'unknown')),
  provenance text not null default 'icmr_nin_traditional_knowledge',
  metadata_status text not null default 'verified',
  created_at timestamptz not null default now(),
  unique (ingredient_key, season, region)
);

create index if not exists idx_ingredient_seasonality_key on public.ingredient_seasonality(ingredient_key);
create index if not exists idx_ingredient_seasonality_season on public.ingredient_seasonality(season);

-- RLS Security Policies
alter table public.ingredient_seasonality enable row level security;
drop policy if exists ingredient_seasonality_select_all on public.ingredient_seasonality;
create policy ingredient_seasonality_select_all on public.ingredient_seasonality for select using (true);

